1	import {
2	  DatabaseOutlined,
3	  FileOutlined,
4	  FolderOpenOutlined,
5	  FolderOutlined,
6	  TableOutlined,
7	} from '@ant-design/icons';
8	import { Alert, Breadcrumb, Button, Empty, Flex, Modal, Spin, Typography } from 'antd';
9	import axios from 'axios';
10	import { type ReactNode, useEffect, useState } from 'react';
11	
12	import {
13	  browseCatalog,
14	  browseFiles,
15	  type CatalogBrowse,
16	  type FileBrowse,
17	} from '../../api/connections';
18	import { errorMessage } from '../../utils/errors';
19	import { SimpleList } from '../SimpleList';
20	
21	type Load<T> =
22	  | { status: 'loading' }
23	  | { status: 'ok'; data: T }
24	  | { status: 'error'; message: string };
25	
26	/** The envelope message plus the backend's classified, secret-free `detail.reason` on a 502. */
27	function browseErrorMessage(err: unknown): string {
28	  const reason = axios.isAxiosError(err)
29	    ? (err.response?.data as { error?: { detail?: { reason?: unknown } } } | undefined)?.error
30	        ?.detail?.reason
31	    : undefined;
32	  return [errorMessage(err), typeof reason === 'string' ? reason : '']
33	    .filter(Boolean)
34	    .join(' ');
35	}
36	
37	/**
38	 * Fetch `load(signal)` whenever `key` changes while `open`, aborting the superseded request — a
39	 * fast click-through must not leave listings running against the datasource.
40	 */
41	function useListing<T>(open: boolean, key: string, load: (signal: AbortSignal) => Promise<T>) {
42	  const [state, setState] = useState<{ key: string; load: Load<T> } | null>(null);
43	  useEffect(() => {
44	    if (!open) return;
45	    const controller = new AbortController();
46	    setState({ key, load: { status: 'loading' } });
47	    load(controller.signal)
48	      .then((data) => {
49	        if (!controller.signal.aborted) setState({ key, load: { status: 'ok', data } });
50	      })
51	      .catch((err: unknown) => {
52	        if (!controller.signal.aborted) {
53	          setState({ key, load: { status: 'error', message: browseErrorMessage(err) } });
54	        }
55	      });
56	    return () => controller.abort();
57	    // `load` is rebuilt every render; `key` is its identity.
58	    // eslint-disable-next-line react-hooks/exhaustive-deps
59	  }, [open, key]);
60	  // A stored answer for an older key is never shown under the new one.
61	  return state && state.key === key ? state.load : ({ status: 'loading' } as Load<T>);
62	}
63	
64	function TruncatedNote({ limit, noun }: { limit: number; noun: string }) {
65	  return (
66	    <Alert
67	      type="info"
68	      showIcon
69	      style={{ marginBottom: 8 }}
70	      title={`Showing the first ${limit} ${noun} — there are more at this level.`}
71	      description="If yours isn't listed, close this and type it into the field instead."
72	    />
73	  );
74	}
75	
76	function ListingBody<T>({
77	  load,
78	  render,
79	}: {
80	  load: Load<T>;
81	  render: (data: T) => ReactNode;
82	}) {
83	  if (load.status === 'loading') {
84	    return (
85	      <Flex justify="center" style={{ padding: 24 }}>
86	        <Spin aria-label="Loading listing" />
87	      </Flex>
88	    );
89	  }
90	  if (load.status === 'error') {
91	    return <Alert
92	        type="error"
93	        showIcon
94	        title="Couldn't list the datasource"
95	        description={load.message}
96	      />;
97	  }
98	  return <>{render(load.data)}</>;
99	}
100	
101	/** A breadcrumb step you can go back to — a real button, so it is keyboard-reachable. */
102	function Crumb({ label, onClick }: { label: string; onClick: () => void }) {
103	  return (
104	    <Button type="link" size="small" onClick={onClick} style={{ padding: 0, height: 'auto' }}>
105	      {label}
106	    </Button>
107	  );
108	}
109	
110	const UNSELECTABLE_HINT =
111	  'DataQ can only target plain identifiers (letters, digits, _ and $, not starting with a digit).';
112	
113	export interface PickedTable {
114	  catalog: string;
115	  schema: string;
116	  table: string;
117	}
118	
119	/**
120	 * Unity Catalog run-target picker: catalogs → schemas → tables, one level per request. The typed
121	 * fields stay the source of truth — picking a table only fills them.
122	 */
123	export function CatalogBrowserButton({
124	  connectionId,
125	  onPick,
126	}: {
127	  connectionId: string;
128	  onPick: (picked: PickedTable) => void;
129	}) {
130	  const [open, setOpen] = useState(false);
131	  const [path, setPath] = useState<string[]>([]);
132	  const [catalog, schema] = path;
133	  const load = useListing<CatalogBrowse>(open, JSON.stringify([connectionId, ...path]), (signal) =>
134	    browseCatalog(connectionId, { catalog, schema }, signal),
135	  );
136	
137	  const noun = path.length === 0 ? 'catalogs' : path.length === 1 ? 'schemas' : 'tables';
138	  const icon =
139	    path.length === 0 ? <DatabaseOutlined /> : path.length === 1 ? <FolderOutlined /> : <TableOutlined />;
140	  const emptyText =
141	    path.length === 0
142	      ? "No catalogs are visible to this connection's credential."
143	      : path.length === 1
144	        ? `No schemas in ${catalog} are visible to this connection's credential.`
145	        : `No tables in ${catalog}.${schema} are visible to this connection's credential.`;
146	
147	  const choose = (name: string) => {
148	    if (path.length < 2) {
149	      setPath([...path, name]);
150	      return;
151	    }
152	    onPick({ catalog: catalog as string, schema: schema as string, table: name });
153	    setOpen(false);
154	  };
155	
156	  return (
157	    <>
158	      <Button
159	        size="small"
160	        icon={<FolderOpenOutlined />}
161	        onClick={() => {
162	          setPath([]);
163	          setOpen(true);
164	        }}
165	        style={{ marginBottom: 12 }}
166	      >
167	        Browse catalog…
168	      </Button>
169	      <Modal
170	        title="Pick a table"
171	        open={open}
172	        onCancel={() => setOpen(false)}
173	        footer={null}
174	        destroyOnHidden
175	      >
176	        <Breadcrumb
177	          style={{ marginBottom: 12 }}
178	          items={[
179	            { title: path.length ? <Crumb label="Catalogs" onClick={() => setPath([])} /> : 'Catalogs' },
180	            ...path.map((part, i) => ({
181	              title:
182	                i < path.length - 1 ? (
183	                  <Crumb label={part} onClick={() => setPath(path.slice(0, i + 1))} />
184	                ) : (
185	                  part
186	                ),
187	            })),
188	          ]}
189	        />
190	        <ListingBody
191	          load={load}
192	          render={(data) => (
193	            <>
194	              {data.truncated && <TruncatedNote limit={data.limit} noun={noun} />}
195	              {data.entries.length === 0 && <Empty description={emptyText} />}
196	              <SimpleList
197	                size="small"
198	                dataSource={data.entries}
199	                rowKey="name"
200	                style={{ maxHeight: 360, overflowY: 'auto' }}
201	                renderItem={(entry) => (
202	                  <SimpleList.Item>
203	                    <Button
204	                      type="link"
205	                      icon={icon}
206	                      disabled={!entry.selectable}
207	                      title={entry.selectable ? undefined : UNSELECTABLE_HINT}
208	                      onClick={() => choose(entry.name)}
209	                      style={{ padding: 0 }}
210	                    >
211	                      {entry.name}
212	                    </Button>
213	                  </SimpleList.Item>
214	                )}
215	              />
216	            </>
217	          )}
218	        />
219	      </Modal>
220	    </>
221	  );
222	}
223	
224	/** `raw/2026/` → `['raw', '2026']`. */
225	function prefixSegments(prefix: string): string[] {
226	  return prefix.split('/').filter(Boolean);
227	}
228	
229	/** The last path segment of a key, for display inside its folder. */
230	function leaf(key: string): string {
231	  const parts = key.split('/').filter(Boolean);
232	  return parts[parts.length - 1] ?? key;
233	}
234	
235	function formatSize(bytes: number | null): string {
236	  if (bytes === null) return '';
237	  if (bytes < 1024) return `${bytes} B`;
238	  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
239	  return `${(bytes / 1024 / 1024).toFixed(1)} MB`;
240	}

